import{_ as t,a,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse(`{"title":"第一册：英语初阶 · Lesson 127 A famous actress","description":"学习 must/cannot 表现在推断，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 127 A famous actress","description":"学习 must/cannot 表现在推断，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 must/cannot 表现在推断，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 126 Have to and do not need to","link":"/life/english/new-concept/book-1/unit-06/lesson-126"},"next":{"text":"第一册：英语初阶 · Lesson 128 He can't be ... He must be ...","link":"/life/english/new-concept/book-1/unit-06/lesson-128"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 126 Have to and do not need to","link":"/life/english/new-concept/book-1/unit-06/lesson-126"},"next":{"text":"第一册：英语初阶 · Lesson 128 He can't be ... He must be ...","link":"/life/english/new-concept/book-1/unit-06/lesson-128"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-06/lesson-127.md","filePath":"life/english/new-concept/book-1/unit-06/lesson-127.md"}`),s={name:"life/english/new-concept/book-1/unit-06/lesson-127.md"};function i(r,e,l,c,d,h){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第一册-英语初阶-·-lesson-127-a-famous-actress" tabindex="-1">第一册：英语初阶 · Lesson 127 A famous actress <a class="header-anchor" href="#第一册-英语初阶-·-lesson-127-a-famous-actress" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 127 A famous actress&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-06/overview">单元 6</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-128">配套课 Lesson 128</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>根据线索推测身份或当前状态 本课要掌握must/cannot 表现在推断，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。先根据情境判断为什么要这样问或这样说，再看语言形式。</p><p>本课为情景学习；完成后进入相邻偶数课进行句型迁移。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>famous</td><td>/ˈfeɪməs/</td><td>adj.</td><td>著名的</td><td>a famous actor</td></tr><tr><td>actress</td><td>/ˈæktrəs/</td><td>n.</td><td>女演员</td><td>a stage actress</td></tr><tr><td>recognise</td><td>/ˈrekəɡnaɪz/</td><td>v.</td><td>认出</td><td>recognise a voice</td></tr><tr><td>sure</td><td>/ʃʊə/</td><td>adj.</td><td>确定的</td><td>be sure</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>must be — 有根据的强推断</li><li>cannot be — 有根据地否定可能</li></ul><h2 id="语法讲解-must-cannot-表现在推断" tabindex="-1">语法讲解：must/cannot 表现在推断 <a class="header-anchor" href="#语法讲解-must-cannot-表现在推断" aria-label="Permalink to &quot;语法讲解：must/cannot 表现在推断&quot;">​</a></h2><p>must be 在推断中表示根据证据很有把握，不能译为命令意义的“必须是”。can&#39;t be 表根据证据认为不可能；may/might be 表不确定的可能。推断应说明证据，不能把 must 当成证明。情态动词后用原形 be，即便主语是 he/she 也不改为 is。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The office lights are on; someone must be inside.</p></blockquote><p>办公室灯亮着，里面一定有人。</p><p>前半句灯亮着是观察线索；后半句 must be 是强推断，someone 是主语，inside 为地点表语。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>mustn&#39;t be 表禁止时不等于不可能；推断不可能常用 can&#39;t be。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“The office lights are on; someone must be inside.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The office lights are on; someone must be inside. That cannot be our bus; it has a different number.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“根据线索推测身份或当前状态”写两至三句，再读给同伴听。至少使用一次must/cannot 表现在推断，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>前半句灯亮着是观察线索；后半句 must be 是强推断，someone 是主语，inside 为地点表语。 Cannot be 表不可能是；分号后 different number 提供推断依据，its number 与 expected bus number 不同。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>表达强推断：Someone ___ be inside.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> must</p><p><strong>解析：</strong> 按本课规则判断：must be 在推断中表示根据证据很有把握，不能译为命令意义的“必须是”。can&#39;t be 表根据证据认为不可能；may/might be 表不确定的可能。推断应说明证据，不能把 must 当成证明。情态动词后用原形 be，即便主语是 he/she 也不改为 is。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“办公室灯亮着，里面一定有人。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The office lights are on; someone must be inside.</p><p><strong>解析：</strong> 前半句灯亮着是观察线索；后半句 must be 是强推断，someone 是主语，inside 为地点表语。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：That cannot be our bus; it has a different number.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 那不可能是我们的公交车，它的编号不同。</p><p><strong>解析：</strong> Cannot be 表不可能是；分号后 different number 提供推断依据，its number 与 expected bus number 不同。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：must/cannot 表现在推断。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-06/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-06/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-06/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-126">上一课</a> · <a href="/life/english/new-concept/book-1/unit-06/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-128">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=t(s,[["render",i]]);export{b as __pageData,m as default};
